CREATE TABLE "AssetsFrontend" (
  "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NameImage" varchar(255),
  "KeyImage" varchar(500),
  "AssetType" int,
  "CreatedAt" timestamp
);

